    pointConstraint -remove; orientConstraint -remove;
    duplicate -n ($item + "_def") $cstname;
    duplicate -n ($item + "_rotate_bst") $cstname;
    duplicate -n ($item + "_walk") $cstname;
    duplicate -n ($item + "_up") $cstname;
