    duplicate -n ($item + "_output") $cstname;
    parent ($item + "_output") ($item + "_down");
    parent ($item + "_down") ($item + "_up");
    parent ($item + "_up") ($item + "_walk");
    parent ($item + "_walk") ($item + "_rotate_bst");
    parent ($item + "_rotate_bst") ($item + "_def");
    parent ($item + "_def") $cstname;

    addAttr -ln "ctrlType"  -at "enum" -en "r:tr:" $cstname;
    setAttr -e-keyable true ($cstname + ".ctrlType");
}
@end

